from pathlib import Path
from html import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Preformatted, PageBreak
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT

out=Path('output/pdf/pizzahub-mongodb-session-fix.pdf')
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleCustom',fontName='Helvetica-Bold',fontSize=25,leading=30,textColor=colors.HexColor('#173c37'),spaceAfter=16))
styles.add(ParagraphStyle(name='SectionCustom',fontName='Helvetica-Bold',fontSize=15,leading=20,textColor=colors.HexColor('#173c37'),spaceBefore=13,spaceAfter=8))
styles.add(ParagraphStyle(name='BodyCustom',fontName='Helvetica',fontSize=11,leading=16,spaceAfter=10))
styles.add(ParagraphStyle(name='CodeCustom',fontName='Courier',fontSize=8.3,leading=12,backColor=colors.HexColor('#eff4f3'),borderPadding=10,spaceBefore=6,spaceAfter=15))
styles.add(ParagraphStyle(name='SmallCustom',fontName='Helvetica',fontSize=9,leading=13,spaceAfter=8))
story=[]
def p(t): story.append(Paragraph(t,styles['BodyCustom']))
def h(t): story.append(Paragraph(t,styles['SectionCustom']))
def title(n,t):
 story.append(Paragraph('PIZZAHUB / PRACTICAL DEBUGGING GUIDE',styles['SmallCustom']))
 story.append(Paragraph(t,styles['TitleCustom']))
def code(t): story.append(Preformatted(t.strip(),styles['CodeCustom']))
def page(): story.append(PageBreak())
def footer(c,d):
 c.setStrokeColor(colors.HexColor('#d4dfdc'));c.line(45,42,550,42)
 c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#526560'))
 c.drawString(45,29,'PizzaHub | MongoDB session error | 23 November 2026')
 c.drawRightString(550,29,str(d.page))

title(1,'Why the session request failed')
p('A simple explanation of the Vercel error, the code changes, and how to avoid repeating the same connection-management mistake.')
h('1. Read the error from the inside out')
code('500 INTERNAL_SERVER_ERROR\nFAILED_TO_GET_SESSION\nCause: MongoTopologyClosedError: Topology is closed')
p('<b>Topology is closed:</b> the MongoDB driver\'s connection-management object was closed when a database operation tried to use it. "Topology" is the driver\'s view of the database servers and their connections.')
p('<b>Failed to get session:</b> Better Auth could not finish checking the signed-in user because its database operation failed.')
p('<b>500:</b> the server could not finish the request. The browser displays this general status; the server log contains the useful cause.')
h('2. What we know - and what we do not')
p('The log confirms a closed MongoDB topology during a session lookup. The code had separate MongoDB clients for authentication and vendor information, with no explicit connection check before those operations.')
p('We found <b>no explicit client.close() call</b> in the application code we searched. We have not proved what originally closed the topology. An earlier connection failure is one possibility, not a confirmed diagnosis.')
h('3. The change in one sentence')
p('<b>Reuse a shared MongoDB client, then await its connection before using the database.</b> This improves connection management and lets the driver establish a connection again when the topology is closed.')
p('This was a database/session error. Saving user details in local storage or adding a skeleton would not repair the database connection.')

page();title(2,'Before: separate clients')
h('Authentication: app/lib/auth.ts')
p('Previously, authentication created its own client. These are the relevant original lines:')
code('import { MongoClient } from "mongodb";\n\nconst client = new MongoClient(\n  process.env.MONGODB_URI as string\n);\nconst db = client.db("pizzahub");\n\nexport const auth = betterAuth({\n  database: mongodbAdapter(db, { client }),\n  // Other authentication settings...\n});')
h('Vendor information: app/lib/vendor-business-names.ts')
p('This file created another client independently:')
code('const client = new MongoClient(\n  process.env.MONGODB_URI as string\n);\n\nconst vendors = await client\n  .db("pizzahub")\n  .collection("user")\n  .find(/* vendor filter and projection */)\n  .toArray();')
h('Why change this?')
p('<b>Two places owned connection setup.</b> Each MongoClient manages its own connection pool. Sharing the client avoids these separate pools within the same server instance.')
p('<b>Database selection is not a connection check.</b> client.db("pizzahub") creates a database handle. It does not itself confirm that MongoDB is reachable.')
p('<b>Automatic connection is normally supported.</b> The old code was not automatically invalid: the driver can connect when a query first runs. The change adds an explicit connection step so closed-topology recovery is handled before the query.')
p('Two clients alone do not prove the cause of this error. They were a connection-management weakness we improved, not a confirmed explanation for the closure.')

page();title(3,'Added: one shared connection helper')
p('<b>New file:</b> app/lib/mongodb.ts. The code below matches the implementation, with comments omitted for readability.')
code('import "server-only"\nimport { MongoClient } from "mongodb"\n\nconst uri = process.env.MONGODB_URI\nif (!uri) throw new Error("MONGODB_URI is not configured")\n\nconst mongoGlobal = globalThis as typeof globalThis & {\n  pizzaHubMongoClient?: MongoClient\n}\n\nexport const mongoClient =\n  mongoGlobal.pizzaHubMongoClient ?? new MongoClient(uri)\nmongoGlobal.pizzaHubMongoClient = mongoClient\n\nexport async function connectMongoDB() {\n  await mongoClient.connect()\n  return mongoClient.db("pizzahub")\n}')
h('What each part means')
p('<b>server-only:</b> prevents this database module from being imported into browser code. The MongoDB connection string belongs on the server.')
p('<b>The environment check:</b> gives a clear message if MONGODB_URI is missing. The old "as string" was only a TypeScript assertion; it did not check the actual value.')
p('<b>globalThis:</b> stores the client in the current server process so modules can reuse it. The type declaration tells TypeScript about our custom property; it does not open a connection.')
p('<b>??:</b> means "use the existing client if present; otherwise create one." This also helps preserve the client during development module reloads.')
p('<b>await mongoClient.connect():</b> waits for connection setup. The installed driver returns quickly when already connected, shares concurrent connection attempts, and can establish a new topology when the old one is closed.')
p('<b>No permanently cached promise:</b> if a connection attempt fails, a later call can try again. We also do not close the shared client after each request.')
p('<b>Vercel limit:</b> this is one client per running server instance, not one client shared by every Vercel instance. A fresh instance creates its own client.')

page();title(4,'Changed: auth and vendor lookups')
h('Authentication now uses the shared helper')
code('import { createAuthMiddleware } from "better-auth/api";\nimport { connectMongoDB, mongoClient } from "./mongodb";\n\nconst db = mongoClient.db("pizzahub");\n\nexport const auth = betterAuth({\n  database: mongodbAdapter(db, {\n    client: mongoClient,\n  }),\n  hooks: {\n    before: createAuthMiddleware(async () => {\n      await connectMongoDB();\n    }),\n  },\n  // Existing authentication settings remain here.\n});')
p('<b>Removed:</b> the MongoClient import and the separate new MongoClient(...) from auth.ts. <b>Added:</b> imports from the shared helper and a Better Auth before hook. The hook waits for a connection before the auth endpoint runs, including session lookup. It also applies to other auth endpoints.')
h('Vendor queries now connect before reading')
code('import { ObjectId } from "mongodb"\nimport { connectMongoDB } from "./mongodb"\n\n// Inside withVendorBusinessNames, after checking IDs:\nconst db = await connectMongoDB()\nconst vendors = await db\n  .collection("user")\n  .find(/* existing filter and projection */)\n  .toArray()')
p('<b>Removed:</b> the second new MongoClient(...) and its MongoClient import. <b>Kept:</b> ObjectId, because it is still used to validate and convert vendor IDs. The query filter, selected fields, and result mapping stay the same.')
h('The new request flow')
p('<b>Request arrives → before hook → await connection → session query → response.</b> Vendor lookups use the same helper directly before their query.')
p('The code excerpts above show only connection-related changes. Existing roles, password login, Google login, subscription fields, and order/payment behavior were not changed by this fix.')

page();title(5,'How to check it and prevent repeats')
h('After deploying')
p('<b>1. Redeploy the updated code.</b> A local change does not update the running Vercel application. Check that MONGODB_URI is set for the deployment environment you are testing, such as Production or Preview.')
p('<b>2. Test the actual flow.</b> Sign in, reload, open the dashboard, and visit a page that shows vendor names. Repeat after the application has been idle. Check Vercel logs for FAILED_TO_GET_SESSION and MongoTopologyClosedError.')
p('<b>3. If it still fails, inspect the earliest related error.</b> Check MongoDB availability, Atlas network access rules, credentials, DNS/TLS connectivity, and connection limits. The closed-topology message can be a follow-up symptom of an earlier failure.')
h('Habits to keep')
p('<b>Reuse the helper.</b> For new server-side MongoDB queries, use await connectMongoDB() and then the returned database handle. Avoid adding new independent clients in each feature.')
p('<b>Do not close the shared client after a request.</b> Another request may still be using it. Closing a client is appropriate for a finished standalone script or controlled shutdown, not routine request cleanup.')
p('<b>Keep failures honest.</b> A database outage should not silently become "user is signed out." Do not automatically retry order creation or payment writes without duplicate-prevention design.')
p('<b>Keep secrets private.</b> Never put MONGODB_URI in local storage, browser code, screenshots, or shared logs. It should not use a NEXT_PUBLIC_ prefix.')
h('What was verified')
p('ESLint, TypeScript checking, and a diff whitespace check passed for this change. These checks validate code structure and types; they do not prove a successful MongoDB connection on Vercel. Production verification was still pending when this guide was written.')
p('This fix improves reuse and recovery. It cannot guarantee that database outages or network failures will never happen, and it does not retry a query that fails after the connection check.')
h('Reference')
story.append(Paragraph('MongoDB: <link href="https://www.mongodb.com/docs/drivers/node/current/connect/connection-options/connection-pools/" color="#176c61">Manage Connections with Connection Pools</link>. The driver recommends reusing a client for operations within a process. The project\'s installed MongoDB driver and Better Auth dispatcher were also inspected to check connection and before-hook behavior.', styles['SmallCustom']))

SimpleDocTemplate(str(out),pagesize=(595.28,841.89),rightMargin=45,leftMargin=45,topMargin=43,bottomMargin=58,title='Understanding the PizzaHub MongoDB Session Fix',author='PizzaHub technical guide').build(story,onFirstPage=footer,onLaterPages=footer)
print(out.resolve())
